function createSafeAsyncAccumulator(initialVal = 0) {
  let state = initialVal;

  function update(fn) {
    state = fn(state);
  }

  async function addAsync(amount, delayMs = 10) {
    await new Promise(r => setTimeout(r, delayMs));
    update(prev => prev + amount);
    return state;
  }

  return {
    getState: () => state,
    addAsync
  };
}
